          "default": 0,
          "maximum": 10,
          "minimum": 0,
          "title": "Usd Limit",
          "type": "number"
        },
        "instructions": {
          "maxLength": 8192,
          "minLength": 1,
          "title": "Instructions",
          "type": "string"
        },
        "model_calls_per_event": {
          "default": 4,
          "maximum": 8,
          "minimum": 1,
          "title": "Model Calls Per Event",
          "type": "integer"
        },
        "model_calls_per_run": {
          "default": 32,
          "maximum": 100,
          "minimum": 1,
          "title": "Model Calls Per Run",
          "type": "integer"
