          "type": "integer"
        },
        "model_usd": {
          "const": 0,
          "default": 0,
          "title": "Model Usd",
          "type": "integer"
        }
      },
      "title": "RoleLimits",
      "type": "object"
    },
    "VertexProfile": {
      "additionalProperties": false,
      "description": "Operator-approved deployment profile; contains no keys or arbitrary endpoints.",
      "properties": {
        "project": {
          "pattern": "^[a-z][a-z0-9-]{4,28}[a-z0-9]$",
