infra/gcp-ai/bigquery.tf:
# Opt-in analytics. Default plans create no BigQuery storage, API or identity.
variable "enable_bigquery" {
  description = "Explicitly provision the bounded analytics demo. Remove analytics before unlinking billing."
  type        = bool
  default     = false
}

variable "bigquery_dataset_id" {
  type    = string
  default = "delivery_analytics"
  validation {
    condition     = can(regex("^[A-Za-z_][A-Za-z0-9_]{0,100}$", var.bigquery_dataset_id))
    error_message = "Use a simple BigQuery dataset identifier."
  }
}

variable "bigquery_location" {
  description = "BigQuery data location; independent of the inference region."
  type        = string
  default     = "EU"
}

resource "google_project_service" "bigquery" {
  count              = var.enable_bigquery || var.enable_analytics ? 1 : 0
  project            = google_project.ai.project_id
  service            = "bigquery.googleapis.com"
  disable_on_destroy = false
}

resource "google_bigquery_dataset" "analytics" {
  count                           = var.enable_bigquery ? 1 : 0
  project                         = google_project.ai.project_id
  dataset_id                      = var.bigquery_dataset_id
  location                        = var.bigquery_location
  description                     = "Allowlisted simulation run receipts and KPIs; seven-day partition retention."
  default_partition_expiration_ms = 604800000
  delete_contents_on_destroy      = false
  labels                          = { application = "madrid-delivery-sim", component = "analytics" }
  lifecycle {
    precondition {
      condition     = var.enable_billing
      error_message = "Analytics requires explicit billing opt-in. Remove analytics while billing is enabled before parking."
    }
    precondition {
      condition     = !var.enable_analytics || var.bigquery_dataset_id != "mds_analytics"
      error_message = "Receipt exports and streaming observability require distinct dataset IDs; mds_analytics belongs to streaming observability."
    }
  }
  depends_on = [google_project_service.bigquery]
}

locals {
  analytics_common_schema = [
    { name = "run_id", type = "STRING", mode = "REQUIRED" },
    { name = "receipt_sha256", type = "STRING", mode = "REQUIRED" },
    { name = "run_created_at", type = "TIMESTAMP", mode = "REQUIRED" },
    { name = "exported_at", type = "TIMESTAMP", mode = "REQUIRED" },
  ]
  analytics_schemas = {
    run_receipts = concat(local.analytics_common_schema, [
      { name = "source_fingerprint", type = "STRING", mode = "NULLABLE" },
      { name = "profile", type = "STRING", mode = "NULLABLE" },
      { name = "scenario", type = "STRING", mode = "NULLABLE" },
      { name = "variant", type = "STRING", mode = "NULLABLE" },
      { name = "status", type = "STRING", mode = "NULLABLE" },
      { name = "replay_matches", type = "BOOLEAN", mode = "NULLABLE" },
      { name = "checks_passed", type = "INTEGER", mode = "REQUIRED" },
      { name = "checks_total", type = "INTEGER", mode = "REQUIRED" },
      { name = "usage_cost_usd", type = "FLOAT", mode = "NULLABLE" },
      { name = "reserved_cost_usd", type = "FLOAT", mode = "NULLABLE" },
      { name = "unknown_usage_calls", type = "INTEGER", mode = "NULLABLE" },
    ])
    run_kpis = concat(local.analytics_common_schema, [
      { name = "metric_name", type = "STRING", mode = "REQUIRED" },
      { name = "metric_value", type = "FLOAT", mode = "REQUIRED" },
    ])
  }
}

resource "google_bigquery_table" "analytics" {
  for_each            = var.enable_bigquery ? local.analytics_schemas : {}
  project             = google_project.ai.project_id
  dataset_id          = google_bigquery_dataset.analytics[0].dataset_id
  table_id            = each.key
  deletion_protection = false # Explicit opt-out removes this disposable seven-day demo.
  schema              = jsonencode(each.value)
  clustering          = ["run_id", "receipt_sha256"]
  time_partitioning {
    type          = "DAY"
    field         = "exported_at"
    expiration_ms = 604800000
  }
  require_partition_filter = true
}

resource "google_bigquery_table" "dashboard" {
  count               = var.enable_bigquery ? 1 : 0
  project             = google_project.ai.project_id
  dataset_id          = google_bigquery_dataset.analytics[0].dataset_id
  table_id            = "run_dashboard"
  deletion_protection = false
  description         = "One latest receipt per run, with delivery, queue, evaluation and cost KPIs for Looker Studio."
  view {
    use_legacy_sql = false
    query = templatefile("${path.module}/sql/run_dashboard.sql", {
      project_id = google_project.ai.project_id
      dataset_id = var.bigquery_dataset_id
    })
  }
  depends_on = [google_bigquery_table.analytics]
}

resource "google_service_account" "analytics" {
  count        = var.enable_bigquery ? 1 : 0
  project      = google_project.ai.project_id
  account_id   = "delivery-analytics"
  display_name = "Bounded simulation receipt loader"
  depends_on   = [google_project_service.api]
}

# No data read, delete, IAM administration or prediction permissions.
resource "google_project_iam_custom_role" "analytics_load" {
  count       = var.enable_bigquery ? 1 : 0
  project     = google_project.ai.project_id
  role_id     = "deliveryAnalyticsLoad"
  title       = "Load simulation analytics tables"
  permissions = ["bigquery.tables.create", "bigquery.tables.get", "bigquery.tables.update", "bigquery.tables.updateData"]
  depends_on  = [google_project_service.bigquery]
}

resource "google_bigquery_dataset_iam_member" "analytics_load" {
  count      = var.enable_bigquery ? 1 : 0
  project    = google_project.ai.project_id
  dataset_id = google_bigquery_dataset.analytics[0].dataset_id
  role       = google_project_iam_custom_role.analytics_load[0].name
  member     = "serviceAccount:${google_service_account.analytics[0].email}"
}

resource "google_project_iam_custom_role" "analytics_jobs" {
  count       = var.enable_bigquery ? 1 : 0
  project     = google_project.ai.project_id
  role_id     = "deliveryAnalyticsJobs"
  title       = "Create simulation analytics load jobs"
  permissions = ["bigquery.jobs.create"]
  depends_on  = [google_project_service.bigquery]
}

resource "google_project_iam_member" "analytics_jobs" {
  count   = var.enable_bigquery ? 1 : 0
  project = google_project.ai.project_id
  role    = google_project_iam_custom_role.analytics_jobs[0].name
  member  = "serviceAccount:${google_service_account.analytics[0].email}"
}

resource "google_service_account_iam_binding" "analytics_tokens" {
  count              = var.enable_bigquery ? 1 : 0
  service_account_id = google_service_account.analytics[0].name
  role               = "roles/iam.serviceAccountTokenCreator"
  members            = var.invoker_members
}

output "bigquery_analytics" {
  value = var.enable_bigquery ? {
    dataset         = "${google_project.ai.project_id}.${var.bigquery_dataset_id}"
    location        = var.bigquery_location
    dashboard_view  = "${google_project.ai.project_id}.${var.bigquery_dataset_id}.run_dashboard"
    service_account = google_service_account.analytics[0].email
  } : null
}

infra/gcp-ai/main.tf:
terraform {
  required_version = ">= 1.6"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 7.0"
    }
  }
  # Deliberately local and unique; never use another project's backend/state.
  backend "local" { path = "terraform.tfstate" }
}

provider "google" {}

resource "google_project" "ai" {
  project_id          = var.project_id
  name                = "Madrid simulation AI"
  billing_account     = var.enable_billing ? var.billing_account : null
  org_id              = var.org_id
  folder_id           = var.folder_id
  auto_create_network = false
  deletion_policy     = "PREVENT"
  labels              = { application = "madrid-delivery-sim", component = "optional-ai" }
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = !var.enable_runtime || var.enable_billing
      error_message = "Runtime requires enable_billing=true. Delete runtime first, then disable billing in a second apply."
    }
    precondition {
      condition     = !var.enable_gateway || var.enable_runtime
      error_message = "Gateway requires enable_runtime=true; turn both flags off to park the project."
    }
    precondition {
      condition     = !(var.enable_analytics || var.enable_cloud_trace) || var.enable_billing
      error_message = "Cloud observability requires enable_billing=true. Export retained analytics and explicitly disable observability before unlinking billing."
    }
  }
}

resource "google_project_service" "api" {
  for_each = toset([
    "run.googleapis.com", "artifactregistry.googleapis.com", "aiplatform.googleapis.com",
    "iam.googleapis.com", "iamcredentials.googleapis.com", "cloudresourcemanager.googleapis.com"
  ])
  project            = google_project.ai.project_id
  service            = each.value
  disable_on_destroy = false # Enabled APIs persist without runtime resources or a billing link.
}

resource "google_artifact_registry_repository" "images" {
  count         = var.enable_runtime ? 1 : 0
  project       = google_project.ai.project_id
  location      = var.region
  repository_id = "judgement"
  format        = "DOCKER"
  depends_on    = [google_project_service.api]
}

resource "google_service_account" "judge" {
  count        = 1 # Persistent, non-billable IAM identity or binding.
  project      = google_project.ai.project_id
  account_id   = "judgement-runtime"
  display_name = "Bounded Vertex judgement gateway"
  depends_on   = [google_project_service.api]
}

resource "google_project_iam_custom_role" "judge_predict" {
  count       = 1 # Persistent, non-billable IAM identity or binding.
  project     = google_project.ai.project_id
  role_id     = "boundedJudgePredict"
  title       = "Bounded judge model inference"
  permissions = ["aiplatform.endpoints.predict"]
  depends_on  = [google_project_service.api]
}

resource "google_project_iam_member" "vertex" {
  count   = 1 # Persistent, non-billable IAM identity or binding.
  project = google_project.ai.project_id
  role    = google_project_iam_custom_role.judge_predict[0].name
  member  = "serviceAccount:${google_service_account.judge[0].email}"
}

resource "google_service_account" "caller" {
  count        = 1 # Persistent, non-billable IAM identity or binding.
  project      = google_project.ai.project_id
  account_id   = "judgement-caller"
  display_name = "Keyless local judgement caller"
  depends_on   = [google_project_service.api]
}

# Native ADK inference has its own keyless identity, retained when billing is parked.
resource "google_service_account" "restaurant" {
  project      = google_project.ai.project_id
  account_id   = "restaurant-adk"
  display_name = "Scoped restaurant Vertex inference"
  depends_on   = [google_project_service.api]
}

resource "google_project_iam_member" "restaurant_predict" {
  project = google_project.ai.project_id
  role    = google_project_iam_custom_role.judge_predict[0].name
  member  = "serviceAccount:${google_service_account.restaurant.email}"
}

resource "google_service_account_iam_binding" "restaurant_tokens" {
  service_account_id = google_service_account.restaurant.name
  role               = "roles/iam.serviceAccountTokenCreator"
  members            = var.invoker_members
}

resource "google_service_account_iam_binding" "caller_tokens" {
  count              = 1 # Persistent, non-billable IAM identity or binding.
  service_account_id = google_service_account.caller[0].name
  role               = "roles/iam.serviceAccountTokenCreator"
  members            = var.invoker_members
}

resource "google_cloud_run_v2_service" "judge" {
  count               = var.enable_gateway ? 1 : 0
  project             = google_project.ai.project_id
  name                = "judgement"
  location            = var.region
  deletion_protection = false
  ingress             = "INGRESS_TRAFFIC_ALL" # IAM-authenticated local clients can reach it.
  scaling {
    min_instance_count = 0
    max_instance_count = 1
  }
  template {
    service_account                  = google_service_account.judge[0].email
    timeout                          = "35s"
    max_instance_request_concurrency = 4
    scaling {
      min_instance_count = 0
      max_instance_count = 1
    }
    containers {
      image = var.gateway_image
      resources {
        cpu_idle          = true
        startup_cpu_boost = false
        limits            = { cpu = "1", memory = "512Mi" }
      }
      env {
        name  = "GOOGLE_CLOUD_PROJECT"
        value = google_project.ai.project_id
      }
      env {
        name  = "VERTEX_REGION"
        value = var.vertex_region
      }
      env {
        name  = "VERTEX_MODEL"
        value = var.vertex_model
      }
    }
  }
  lifecycle {
    precondition {
      condition     = !var.enable_gateway || (var.gateway_image != "" && length(var.invoker_members) > 0)
      error_message = "Enabled gateway requires a built image and explicit invoker principals."
    }
  }
  depends_on = [google_project_service.api, google_project_iam_member.vertex]
}

resource "google_cloud_run_v2_service_iam_binding" "invoker" {
  count    = var.enable_gateway ? 1 : 0
  project  = google_project.ai.project_id
  location = var.region
  name     = google_cloud_run_v2_service.judge[0].name
  role     = "roles/run.invoker"
  members  = ["serviceAccount:${google_service_account.caller[0].email}"]
}

output "image_repository" {
  value = try("${var.region}-docker.pkg.dev/${google_project.ai.project_id}/${google_artifact_registry_repository.images[0].repository_id}", null)
}
output "gateway_url" {
  value = try(google_cloud_run_v2_service.judge[0].uri, null)
}
output "caller_service_account" {
  value = try(google_service_account.caller[0].email, null)
}

moved {
  from = google_artifact_registry_repository.images
  to   = google_artifact_registry_repository.images[0]
}

moved {
  from = google_service_account.judge
  to   = google_service_account.judge[0]
}

moved {
  from = google_project_iam_custom_role.judge_predict
  to   = google_project_iam_custom_role.judge_predict[0]
}

moved {
  from = google_project_iam_member.vertex
  to   = google_project_iam_member.vertex[0]
}

moved {
  from = google_service_account.caller
  to   = google_service_account.caller[0]
}

moved {
  from = google_service_account_iam_binding.caller_tokens
  to   = google_service_account_iam_binding.caller_tokens[0]
}

output "runtime_enabled" {
  value = var.enable_runtime
}

output "caller_unique_id" {
  value = google_service_account.caller[0].unique_id
}
output "judge_unique_id" {
  value = google_service_account.judge[0].unique_id
}

infra/gcp-ai/telemetry.tf:
# No collector, API enablement or telemetry identity unless explicitly requested.
variable "enable_telemetry" {
  description = "Provision trace-only APIs and IAM. Does not start a collector or export spans."
  type        = bool
  default     = false
}

resource "google_project_service" "telemetry" {
  for_each = toset(concat(
    var.enable_telemetry ? ["telemetry.googleapis.com", "cloudtrace.googleapis.com"] : [],
    var.enable_cloud_trace ? ["cloudtrace.googleapis.com"] : []
  ))
  project            = google_project.ai.project_id
  service            = each.value
  disable_on_destroy = false
}

resource "google_service_account" "telemetry" {
  count        = var.enable_telemetry ? 1 : 0
  project      = google_project.ai.project_id
  account_id   = "simulation-trace-exporter"
  display_name = "Trace-only simulation collector"
  depends_on   = [google_project_service.api]
}

resource "google_project_iam_member" "telemetry" {
  for_each = var.enable_telemetry ? toset([
    "roles/telemetry.tracesWriter", "roles/serviceusage.serviceUsageConsumer"
  ]) : toset([])
  project = google_project.ai.project_id
  role    = each.value
  member  = "serviceAccount:${google_service_account.telemetry[0].email}"
}

resource "google_service_account_iam_binding" "telemetry_tokens" {
  count              = var.enable_telemetry ? 1 : 0
  service_account_id = google_service_account.telemetry[0].name
  role               = "roles/iam.serviceAccountTokenCreator"
  members            = var.invoker_members
}

output "telemetry_service_account" {
  description = "Trace-only collector identity; null while telemetry is parked."
  value       = var.enable_telemetry ? google_service_account.telemetry[0].email : null
}

