   ELSE outbox:=outbox||jsonb_build_array(public.supply_send(b.run_id,eventid,'market.request',nextmarket,jsonb_build_object('order',oid,'request',rid),sim+latency)); END IF;
  END IF; resultstatus:='restaurant_approved';
