 WHERE run_id=e.run_id AND trace_id=e.trace_id;
 RETURN jsonb_build_object('status',resultstatus,'latency',
  greatest(0,extract(epoch FROM (clock_timestamp()-started))*1000));
END $$;
REVOKE ALL ON FUNCTION public.agent_order_telemetry(bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.agent_order_telemetry(bigint)
 TO lab_inventory_executor,lab_fulfillment_executor,lab_dispatch_executor,
 lab_courier_executor,lab_judge_executor,lab_supply_executor,lab_restaurant_adk_executor;

sql/migrations/031_semantic_memory.sql:
-- Semantic ranking is a projection of current typed facts, never a new authority.
-- The extension is optional on existing installations; semantic mode fails closed
-- without it. The local Postgres build and Cloud SQL setup install pgvector.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_available_extensions WHERE name='vector') THEN
  CREATE EXTENSION IF NOT EXISTS vector;
 END IF;
 EXECUTE replace(pg_get_functiondef('public.agent_memory_profile_valid(jsonb)'::regprocedure),
  '(''none'',''text'',''json'',''typed'')', '(''none'',''text'',''json'',''typed'',''semantic'')');
END $$;

CREATE TABLE public.agent_semantic_vectors (
 fact_id bigint NOT NULL REFERENCES public.agent_memory_facts(id) ON DELETE CASCADE,
 model text NOT NULL CHECK(length(model) BETWEEN 1 AND 150),
 embedding jsonb NOT NULL CHECK(jsonb_typeof(embedding)='array' AND jsonb_array_length(embedding)=384),
 PRIMARY KEY(fact_id,model)
);
REVOKE ALL ON public.agent_semantic_vectors FROM PUBLIC;

CREATE FUNCTION public.agent_semantic_allowed(scope jsonb, factid bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT EXISTS(SELECT 1 FROM public.agent_memory_current m
 JOIN public.agent_memory_types t ON t.kind=m.kind AND t.role=m.owner_role
 JOIN public.agent_bindings b ON b.login_role=session_user
 WHERE m.id=factid AND b.definition->'memory'->>'mode'='semantic'
 AND b.definition->'tools' ? 'memory.read'
 AND m.run_id=(scope->>'run')::uuid AND m.store=scope->>'store'
 AND m.owner_role=scope->>'role' AND m.context_type=scope->>'context_type'
 AND m.context_id=scope->>'context' AND m.expires_sim>(scope->>'sim')::integer
 AND m.observed_sim<=(scope->>'sim')::integer
 AND m.observed_sim+(b.definition->'memory'->>'ttl_seconds')::integer>(scope->>'sim')::integer
 AND (scope->>'role'<>'market' OR m.subject=scope->>'subject')
 AND (scope->>'role'<>'courier' OR m.body->'attempt'=scope->'attempt'));
$$;

CREATE FUNCTION public.agent_semantic_cache(eventid bigint,token uuid,attempt integer,
 modelid text, entries jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE scope jsonb; entry jsonb;
BEGIN
 scope:=public.agent_memory_context(eventid,token,attempt);
 IF length(modelid) NOT BETWEEN 1 AND 150 OR jsonb_typeof(entries)<>'array'
 OR jsonb_array_length(entries)>8 THEN
  RAISE EXCEPTION 'Invalid embedding batch' USING ERRCODE='23514'; END IF;
 FOR entry IN SELECT * FROM jsonb_array_elements(entries) LOOP
  IF NOT public.agent_semantic_allowed(scope,(entry->>'fact_id')::bigint)
  OR jsonb_typeof(entry->'embedding')<>'array' OR jsonb_array_length(entry->'embedding')<>384
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(entry->'embedding') n
            WHERE jsonb_typeof(n)<>'number') THEN
   RAISE EXCEPTION 'Embedding outside active memory scope' USING ERRCODE='42501'; END IF;
  INSERT INTO public.agent_semantic_vectors VALUES
   ((entry->>'fact_id')::bigint,modelid,entry->'embedding') ON CONFLICT DO NOTHING;
 END LOOP;
END $$;

CREATE FUNCTION public.agent_semantic_neighbors(eventid bigint,token uuid,attempt integer,
 modelid text, query_vector jsonb, maximum integer DEFAULT 8) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE scope jsonb; result jsonb;
BEGIN
 scope:=public.agent_memory_context(eventid,token,attempt);
 IF maximum NOT BETWEEN 1 AND 8 OR jsonb_typeof(query_vector)<>'array'
 OR jsonb_array_length(query_vector)<>384 OR NOT EXISTS(
  SELECT 1 FROM pg_extension WHERE extname='vector') THEN
  RAISE EXCEPTION 'Semantic mode requires pgvector and a 384-dimensional query'
  USING ERRCODE='23514'; END IF;
 -- Exact search over the small authorized set, not global ANN followed by a filter.
 EXECUTE 'SELECT coalesce(jsonb_agg(fact_id ORDER BY distance,fact_id),''[]''::jsonb)
 FROM (SELECT v.fact_id,(v.embedding::text::public.vector <=> $1::text::public.vector) distance
 FROM public.agent_semantic_vectors v WHERE v.model=$2
 AND public.agent_semantic_allowed($3,v.fact_id) ORDER BY distance,v.fact_id LIMIT $4) ranked'
 INTO result USING query_vector,modelid,scope,maximum;
 RETURN result;
END $$;

REVOKE ALL ON FUNCTION public.agent_semantic_allowed(jsonb,bigint),
 public.agent_semantic_cache(bigint,uuid,integer,text,jsonb),
 public.agent_semantic_neighbors(bigint,uuid,integer,text,jsonb,integer) FROM PUBLIC;
DO $$ DECLARE role_name text; BEGIN
 FOREACH role_name IN ARRAY ARRAY['lab_inventory_executor','lab_fulfillment_executor',
  'lab_dispatch_executor','lab_courier_executor','lab_judge_executor','lab_supply_executor',
  'lab_restaurant_adk_executor'] LOOP
  EXECUTE format('GRANT EXECUTE ON FUNCTION public.agent_semantic_cache(bigint,uuid,integer,text,jsonb),public.agent_semantic_neighbors(bigint,uuid,integer,text,jsonb,integer) TO %I',role_name);
 END LOOP;
END $$;

src/delivery/a2a_server.py:
"""A2A 1.0 JSON-RPC servers backed by the existing durable agent queue.

Local, bounded adapters accept references to existing simulation entities, never
model tool calls. Customer service retains the configured ADK provider and budgets.
"""

import asyncio
import json
import os
import re
from functools import partial
from typing import Any, Literal
from urllib.parse import urlsplit
from uuid import UUID, uuid4

from a2a.server.agent_execution import AgentExecutor, RequestContext
from a2a.server.events import EventQueue
from a2a.server.request_handlers import DefaultRequestHandler
from a2a.server.routes import create_agent_card_routes, create_jsonrpc_routes
from a2a.server.tasks import InMemoryTaskStore
from a2a.types import (
    AgentCapabilities,
    AgentCard,
    AgentInterface,
    AgentSkill,
    HTTPAuthSecurityScheme,
    Message,
    Part,
    Role,
    SecurityRequirement,
    SecurityScheme,
    StringList,
)
from a2a.utils.errors import InvalidParamsError, UnsupportedOperationError
from pydantic import BaseModel, ConfigDict, Field, ValidationError
from starlette.applications import Starlette
from starlette.middleware import Middleware
from starlette.middleware.base import BaseHTTPMiddleware, RequestResponseEndpoint
from starlette.requests import Request
from starlette.responses import JSONResponse, Response

from delivery.agents import Dispatcher, resolve_complaint
from delivery.config import Settings
from delivery.customer_service import CustomerService
from delivery.db import connect
from delivery.queue import Queue, publish
from delivery.telemetry import trace_span
from delivery.world import World

AgentRole = str
MAX_REQUEST_BYTES = 8192
MAX_EVENTS_PER_REQUEST = 32


class AgentCommand(BaseModel):
    model_config = ConfigDict(extra="forbid")
    run_id: UUID
    operation: Literal["submit", "tick", "supply_tick", "replan", "store_tick"] = "submit"
    entity_id: str = Field(min_length=1, max_length=80, pattern=r"^[A-Za-z0-9_.:-]+$")


class QueuedAgentService:
    def __init__(self, role: AgentRole, url: str | None = None) -> None:
        self.role = role
        self.url = url
        self.customer = CustomerService(url)
        self.world: World | None = None

    def invoke(self, command: AgentCommand) -> dict[str, Any]:
        if command.operation == "store_tick":
            from delivery.store_agents import store_tick

            with trace_span("a2a.invoke", attributes={"agent.role":self.role,
                                                      "delivery.environment":"dark_store"}):
                return store_tick(self.role,str(command.run_id),self.url)
        if command.operation == "replan":
            from delivery.chaos_agents import replan

            return replan(self.role, command, self.url)
        if command.operation == "supply_tick":
            from delivery.supply import process_agent_message

            return process_agent_message(
                str(command.run_id), self.role, command.entity_id, self.url
            )
        if command.operation == "tick":
            return self.tick(command)
        if self.role not in {"dispatcher", "customer_service"}:
            raise ValueError("Restaurants require a scoped supply or replanning message")
        topic = "order.created" if self.role == "dispatcher" else "complaint.created"
        table = "orders" if self.role == "dispatcher" else "complaints"
        field = "order_id" if self.role == "dispatcher" else "complaint_id"
        with trace_span("a2a.invoke", attributes={"agent.role": self.role}):
            with connect(self.url) as conn:
                run = conn.execute(
                    "SELECT status,sim_time FROM runs WHERE id=%s", (command.run_id,)
                ).fetchone()
                entity = conn.execute(
                    f"SELECT * FROM {table} WHERE run_id=%s AND id=%s",
                    (command.run_id, command.entity_id),
                ).fetchone()
                if not run or not entity:
                    raise ValueError("Unknown run or entity")
                existing = conn.execute(
                    "SELECT id FROM events WHERE run_id=%s AND topic=%s AND dedupe_key=%s",
                    (command.run_id, topic, command.entity_id),
                ).fetchone()
                if existing:
                    event_id = existing["id"]
                else:
                    if run["status"] in {"complete", "failed"}:
                        raise ValueError("Cannot enqueue work for a closed run")
                    event_id = publish(
                        conn,
                        run_id=command.run_id,
                        producer="generator",
                        topic=topic,
                        payload={field: command.entity_id},
                        key=command.entity_id,
                        trace_id=entity.get("order_id", command.entity_id),
                        due_sim=run["sim_time"],
                    )
            queue = Queue(self.url)
            if run["status"] in {"complete", "failed"}:
                return self.receipt(command, event_id, table)
            for _ in range(MAX_EVENTS_PER_REQUEST):
                receipt = self.receipt(command, event_id, table)
                if receipt["queue_state"] in {"done", "dead"}:
                    return receipt
                event = queue.claim(
                    self.role, command.run_id, run["sim_time"], accepted_topics=(topic,)
                )
                if event is None:
                    break
                if self.role == "dispatcher":
                    if self.world is None:
                        self.world = World()
                    queue.process(event, Dispatcher(self.world).handle)
                else:
                    advice, source = self.customer.prepare(event)
                    queue.process(event, partial(resolve_complaint, advice=advice, source=source))
            # A concurrent worker or backoff may still own the event. Never claim completion.
            return self.receipt(command, event_id, table)

    def tick(self, command: AgentCommand) -> dict[str, Any]:
        if self.role not in {"dispatcher", "customer_service"}:
            raise ValueError("Unknown scheduler role")
        with connect(self.url) as conn:
            run = conn.execute(
                "SELECT status,sim_time FROM runs WHERE id=%s", (command.run_id,)
            ).fetchone()
        if not run or run["status"] in {"complete", "failed"}:
            raise ValueError("Unknown or closed run")
        queue = Queue(self.url)
        event = queue.claim(self.role, command.run_id, run["sim_time"])
        if event is None:
            return {"progressed": False}
        if self.role == "dispatcher":
            if self.world is None:
                self.world = World()
            ok = queue.process(event, Dispatcher(self.world).handle)
        else:
            advice, source = self.customer.prepare(event)
            ok = queue.process(event, partial(resolve_complaint, advice=advice, source=source))
        return {"progressed": True, "processed": ok, "event_id": event.id}

    def receipt(self, command: AgentCommand, event_id: int, table: str) -> dict[str, Any]:
        with connect(self.url) as conn:
            event = conn.execute(
                "SELECT state,attempts FROM events WHERE id=%s AND run_id=%s",
                (event_id, command.run_id),
            ).fetchone()
            columns = (
                "status,courier"
                if table == "orders"
                else ("status,response,source,approved_refund_eur")
            )
            entity = conn.execute(
                f"SELECT {columns} FROM {table} WHERE run_id=%s AND id=%s",
                (command.run_id, command.entity_id),
            ).fetchone()
        assert event and entity
        return {
            "agent": self.role,
            "run_id": str(command.run_id),
            "entity_id": command.entity_id,
            "event_id": event_id,
            "queue_state": event["state"],
            "attempts": event["attempts"],
            "outcome": entity,
        }


class QueueAgentExecutor(AgentExecutor):
    def __init__(self, service: QueuedAgentService) -> None:
        self.service = service

    async def execute(self, context: RequestContext, event_queue: EventQueue) -> None:
        text = context.get_user_input()
        if len(text.encode("utf-8")) > MAX_REQUEST_BYTES:
            raise InvalidParamsError("Command exceeds byte limit")
        try:
            command = AgentCommand.model_validate_json(text)
        except ValidationError:
            raise InvalidParamsError("Expected JSON with run_id and entity_id") from None
        try:
            result = await asyncio.to_thread(self.service.invoke, command)
        except ValueError:
            raise InvalidParamsError("Unknown entity or closed run") from None
        # Immediate Message workflow; queue receipts persist in Postgres across restarts.
        await event_queue.enqueue_event(
            Message(
                message_id=uuid4().hex,
                context_id=context.context_id,
                role=Role.ROLE_AGENT,
                parts=[Part(text=json.dumps(result, default=str), media_type="text/plain")],
            )
        )

    async def cancel(self, context: RequestContext, event_queue: EventQueue) -> None:
        raise UnsupportedOperationError("Durable events require explicit operator action")


class LocalA2ABoundary(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next: RequestResponseEndpoint) -> Response:
        if (os.environ.get("DELIVERY_RUNTIME", "local") != "live"
                and request.url.hostname not in {"localhost", "127.0.0.1", "::1", "testserver"}):
            return JSONResponse({"detail": "A2A demo is local-only"}, status_code=403)
        origin = request.headers.get("origin")
        if origin and origin != f"{request.url.scheme}://{request.url.netloc}":
            return JSONResponse({"detail": "Cross-origin requests are disabled"}, status_code=403)
        # Bound streamed bodies as well as Content-Length. Cards need no body.
        size = 0
        chunks = []
        async for chunk in request.stream():
            size += len(chunk)
            if size > MAX_REQUEST_BYTES:
                return JSONResponse({"detail": "Request too large"}, status_code=413)
            chunks.append(chunk)
        request._body = b"".join(chunks)
        return await call_next(request)


def agent_card(
    role: AgentRole,
    *,
    base_url: str | None = None,
    live: bool | None = None,
) -> AgentCard:
    if role not in {"dispatcher", "customer_service", "inventory", "fulfillment"} and not (
        re.fullmatch(
            r"restaurant-[a-z0-9_-]{1,80}", role
        )
    ):
        raise ValueError("Unknown A2A role")
    origin = (
        base_url
        if base_url is not None
        else os.environ.get("DELIVERY_A2A_BASE_URL", f"http://localhost:{Settings().app_port}")
    )
    parsed = urlsplit(origin)
    cloud = os.environ.get("DELIVERY_RUNTIME", "local") == "live" if live is None else live
    if cloud and (parsed.scheme != "https" or parsed.username or parsed.query or parsed.fragment
                  or parsed.path not in {"", "/"}):
        raise ValueError("Cloud Agent Card requires an HTTPS service origin")
    if not cloud and (parsed.scheme != "http" or parsed.hostname not in {
        "localhost", "127.0.0.1", "::1"
    }):
        raise ValueError("The demo agent card requires a local HTTP origin")
    endpoint = f"{origin.rstrip('/')}/a2a/{role}/"
    description = (
        "Dispatch existing pending Madrid orders through the durable queue."
        if role == "dispatcher"
        else "Scoped restaurant preparation, sourcing and recovery through ADK tools."
        if role.startswith("restaurant-")
        else "Scoped physical stock reservations and confirmed supply receipts."
        if role == "inventory"
        else "Plan pick routes, pack complete baskets and hand off at the store dock."
        if role == "fulfillment"
        else "ADK customer service; policy-checked advice and proactive recovery tools."
    )
    return AgentCard(
        name=f"Madrid {role.replace('_', ' ')}",
        description=description,
        version="1.0.0",
        supported_interfaces=[
            AgentInterface(
                url=endpoint,
                protocol_binding="JSONRPC",
                protocol_version="1.0",
            )
        ],
        default_input_modes=["text/plain"],
        default_output_modes=["text/plain"],
        capabilities=AgentCapabilities(streaming=False, push_notifications=False),
        security_schemes={"google_id_token": SecurityScheme(
            http_auth_security_scheme=HTTPAuthSecurityScheme(
                scheme="bearer", bearer_format="JWT",
                description="Google-signed ID token for this Cloud Run service audience",
            )
        )} if cloud else {},
        security_requirements=[SecurityRequirement(
            schemes={"google_id_token": StringList(list=[])}
        )] if cloud else [],
        skills=[
            AgentSkill(
                id=role,
                name=role.replace("_", " ").title(),
                description=description,
                tags=["delivery", "durable-queue", "dark-store" if role in
                      {"inventory","fulfillment"} else "adk"],
                examples=[json.dumps({
                    "run_id": "00000000-0000-0000-0000-000000000000",
                    "operation": "store_tick" if role in {"inventory","fulfillment"} else
                        "replan" if role.startswith("restaurant-") else "submit",
                    "entity_id": (
                        "00000000000000000000000000000000" if role.startswith("restaurant-")
                        else "C-1" if role == "customer_service" else "O-1"
                    ),
                })],
            )
        ],
    )


def create_a2a_app(
    role: AgentRole, *, base_url: str | None = None, url: str | None = None,
) -> Starlette:
    card = agent_card(role, base_url=base_url)
    handler = DefaultRequestHandler(
        agent_executor=QueueAgentExecutor(QueuedAgentService(role, url)),
        task_store=InMemoryTaskStore(),
        agent_card=card,
    )
    return Starlette(
        routes=create_agent_card_routes(card) + create_jsonrpc_routes(handler, "/"),
        middleware=[Middleware(LocalA2ABoundary)],
    )

src/delivery/adk_customer.py:
"""One bounded ADK classification turn with a zero-network scripted CI adapter.

Like the restaurant agent, this uses LlmAgent, Runner and BaseLlm. The durable
reservation lives in CustomerService.prepare; this module has no SQL or business
tools. A model may advise, but only the existing deterministic refund policy acts.
"""

import asyncio
import json
from typing import Any

from google.adk.agents import LlmAgent
from google.adk.agents.callback_context import CallbackContext
from google.adk.agents.run_config import RunConfig
from google.adk.models.base_llm import BaseLlm
from google.adk.models.google_llm import Gemini
from google.adk.models.llm_request import LlmRequest
from google.adk.models.llm_response import LlmResponse
from google.adk.runners import Runner
from google.adk.sessions import InMemorySessionService
from google.genai import types
from google.oauth2.credentials import Credentials
from opentelemetry.trace import Span

from delivery.adk_offline import OfflineCustomerModel as OfflineCustomerModel
from delivery.config import Settings
from delivery.customer_service import (
    MAX_OUTPUT,
    RESERVED_TOKENS,
    SYSTEM,
    Advice,
    complaint_prompt,
)
from delivery.telemetry import mark_error, record_model_usage, start_span, trace_span


def create_customer_model(config: Settings) -> BaseLlm:
    """Select only the explicit provider; never fall through to paid inference."""
    if config.llm_provider == "offline":
        return OfflineCustomerModel()
    options: dict[str, Any] = {
        "http_options": types.HttpOptions(
            timeout=15000, retry_options=types.HttpRetryOptions(attempts=1)
        )
    }
    if config.llm_provider == "vertex":
        credentials = None
        if config.google_credentials_json:
            credentials = Credentials.from_authorized_user_info(
                json.loads(config.google_credentials_json),
                scopes=["https://www.googleapis.com/auth/cloud-platform"],
            )
        options.update(
            vertexai=True,
            project=config.google_cloud_project,
            location=config.google_cloud_location,
            credentials=credentials,
        )
    elif config.llm_provider == "gemini":
        options.update(vertexai=False, api_key=config.gemini_api_key)
    else:
        raise ValueError("LLM provider is disabled or unsupported")
    return Gemini(
        model=config.llm_model,
        api_version="v1" if config.llm_provider == "vertex" else None,
        client_kwargs=options,
        retry_options=types.HttpRetryOptions(attempts=1),
    )


class CustomerAdviceTurn:
    """One reserved model call, without tools, history, retries or follow-up turns."""

    def __init__(self, config: Settings) -> None:
        self.config = config
        self.calls = 0
        self.advice: Advice | None = None
        self.usage: types.GenerateContentResponseUsageMetadata | None = None
        self.model_span: Span | None = None

    def before_model(self, callback_context: CallbackContext, llm_request: LlmRequest) -> None:
        del callback_context
        if self.calls:
            raise PermissionError("A customer reservation permits exactly one model call")
        if llm_request.tools_dict or llm_request.config.tools:
            raise PermissionError("Customer classification cannot invoke tools")
        # Bound the complete ADK prompt/config, not just complaint text. Counting
        # UTF-8 bytes conservatively accommodates schema and instruction overhead.
        config_body = llm_request.config.model_dump(
            mode="json", exclude_none=True, exclude={"response_schema"}
        )
        config_body["response_schema"] = Advice.model_json_schema()
        body = json.dumps(
            {
                "contents": [
                    content.model_dump(mode="json", exclude_none=True)
                    for content in llm_request.contents
                ],
                "config": config_body,
            },
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode()
        if len(body) > RESERVED_TOKENS - MAX_OUTPUT:
            raise ValueError("ADK request exceeds its existing input token reservation")
        self.calls += 1
        self.model_span = start_span(
            "agent.model",
            {
                "delivery.agent": "customer_service",
                "gen_ai.system": self.config.llm_provider,
                "gen_ai.request.model": "offline"
                if self.config.llm_provider == "offline"
                else self.config.llm_model,
            },
        )

    def after_model(self, callback_context: CallbackContext, llm_response: LlmResponse) -> None:
        if llm_response.partial:
            return
        try:
            if self.model_span is not None:
                offline = self.config.llm_provider == "offline"
                record_model_usage(
                    self.model_span,
                    llm_response.usage_metadata,
                    0.0 if offline else self.config.llm_input_usd_per_million,
                    0.0 if offline else self.config.llm_output_usd_per_million,
                )
            self._after_model(callback_context, llm_response)
            if self.model_span is not None:
                self.model_span.set_attribute("delivery.success", True)
        except BaseException as exc:
            if self.model_span is not None:
                mark_error(self.model_span, exc)
            raise
        finally:
            if self.model_span is not None:
                self.model_span.end()
                self.model_span = None

    def _after_model(self, callback_context: CallbackContext, llm_response: LlmResponse) -> None:
        del callback_context
        if llm_response.partial:
            return
        if self.advice is not None:
            raise PermissionError("A customer reservation permits exactly one model response")
        if llm_response.error_code or not llm_response.content:
            raise ValueError("Customer model did not return an advice response")
        parts = llm_response.content.parts or []
        if any(part.function_call for part in parts):
            raise PermissionError("Customer classification cannot invoke tools")
        text = "".join(part.text or "" for part in parts if not part.thought)
        self.advice = Advice.model_validate_json(text)
        self.usage = llm_response.usage_metadata

    def build(self, model: BaseLlm) -> LlmAgent:
        return LlmAgent(
            name="customer_service",
            model=model,
            instruction=SYSTEM,
            output_schema=Advice,
            disallow_transfer_to_parent=True,
            disallow_transfer_to_peers=True,
            before_model_callback=self.before_model,
            after_model_callback=self.after_model,
            generate_content_config=types.GenerateContentConfig(
                temperature=0,
                max_output_tokens=MAX_OUTPUT,
                thinking_config=types.ThinkingConfig(thinking_budget=0),
            ),
        )

    async def run(self, model: BaseLlm, complaint: dict[str, Any]) -> tuple[Advice, int, float]:
        with trace_span(
            "agent.customer_service", attributes={"delivery.agent": "customer_service"}
        ):
            try:
                return await self._run(model, complaint)
            except BaseException as exc:
                if self.model_span is not None:
                    mark_error(self.model_span, exc)
                raise
            finally:
                if self.model_span is not None:
                    self.model_span.end()
                    self.model_span = None

    async def _run(self, model: BaseLlm, complaint: dict[str, Any]) -> tuple[Advice, int, float]:
        service = InMemorySessionService()
        session = await service.create_session(app_name="bakiano_customer", user_id="customer")
        runner = Runner(
            app_name="bakiano_customer", agent=self.build(model), session_service=service
        )
        # Capture the per-loop client here so it can be closed on success, timeout,
        # schema rejection and cancellation, without creating a client at cleanup.
        client = model.api_client if isinstance(model, Gemini) else None
        try:
            async for _ in runner.run_async(
                user_id="customer",
                session_id=session.id,
                new_message=types.Content(
                    role="user",
                    parts=[
                        types.Part(
                            text=complaint_prompt(complaint["text"], complaint["order_status"])
                        )
                    ],
                ),
                run_config=RunConfig(max_llm_calls=1),
            ):
                pass
        finally:
            try:
                await runner.close()
            finally:
                if client is not None:
                    try:
                        await client.aio.aclose()
                    finally:
                        client.close()
        if self.advice is None:
            raise ValueError("Customer model did not return validated advice")
        usage = self.usage
        input_tokens = (usage.prompt_token_count or 0) if usage else RESERVED_TOKENS - MAX_OUTPUT
        output_tokens = (usage.candidates_token_count or 0) if usage else MAX_OUTPUT
        thoughts = (usage.thoughts_token_count or 0) if usage else 0
        cost = (
            input_tokens * self.config.llm_input_usd_per_million
            + (output_tokens + thoughts) * self.config.llm_output_usd_per_million
        ) / 1_000_000
        return self.advice, input_tokens + output_tokens + thoughts, cost


async def run_customer_advice(
    config: Settings, complaint: dict[str, Any]
) -> tuple[Advice, int, float]:
    """Execute after the caller has durably reserved its single paid request."""
    return await asyncio.wait_for(
        CustomerAdviceTurn(config).run(create_customer_model(config), complaint), timeout=15
    )

src/delivery/adk_models.py:
"""Explicit, keyless Google Vertex adapter; offline remains the default."""

import os

from google.adk.models.base_llm import BaseLlm
from google.adk.models.google_llm import Gemini
from google.genai import types

from delivery.adk_contracts import RestaurantBrain, VertexProfile
from delivery.adk_offline import OfflineRestaurantModel


def approved_vertex_profile(brain: RestaurantBrain) -> VertexProfile:
    if os.environ.get("DELIVERY_ADK_VERTEX_ENABLED") != "1":
        raise PermissionError("Vertex restaurant inference is disabled by deployment policy")
    if os.environ.get("GOOGLE_API_KEY") or os.environ.get("GEMINI_API_KEY"):
        raise PermissionError("Vertex restaurant inference requires keyless ADC")
    profile = VertexProfile.model_validate_json(os.environ.get("DELIVERY_ADK_VERTEX_PROFILE", "{}"))
    if brain.provider != "vertex" or brain.vertex != profile or brain.usd_limit <= 0:
        raise PermissionError("Restaurant model profile differs from approved deployment policy")
    return profile


def create_restaurant_model(brain: RestaurantBrain) -> BaseLlm:
    if brain.provider == "offline":
        return OfflineRestaurantModel()
    profile = approved_vertex_profile(brain)
    return Gemini(
        model=profile.model,
        api_version="v1",
        client_kwargs={"vertexai": True, "project": profile.project, "location": profile.location},
        retry_options=types.HttpRetryOptions(attempts=1),
    )


def validate_model(brain: RestaurantBrain, model: BaseLlm) -> None:
    if brain.provider == "offline":
        if not isinstance(model, OfflineRestaurantModel):
            raise PermissionError("Only approved offline model adapters are admitted")
        return
    profile = approved_vertex_profile(brain)
    if (
        type(model) is not Gemini
        or model.model != profile.model
        or model.client_kwargs
        != {
            "vertexai": True,
            "project": profile.project,
            "location": profile.location,
        }
        or model.base_url is not None
        or model.client is not None
        or model.use_interactions_api
        or model.api_version != "v1"
    ):
        raise PermissionError("Vertex adapter must use the approved keyless deployment profile")
    if model.retry_options is None or model.retry_options.attempts != 1:
        raise PermissionError("Automatic provider retries are disabled")

src/delivery/adk_offline.py:
"""A scripted ADK model double for reproducible, zero-network contract tests.

This is deliberately not an LLM or a quality evaluation of SOUL understanding.
It exercises Google's real Runner/function-calling loop using the two published
fixture instructions. Production policy code never selects a sourcing strategy.
"""

import json
from collections.abc import AsyncGenerator
from typing import Any, Literal

from google.adk.models.base_llm import BaseLlm
from google.adk.models.llm_request import LlmRequest
from google.adk.models.llm_response import LlmResponse
from google.genai import types

from delivery.customer_service import OFFLINE_MODEL, Advice


class OfflineRestaurantModel(BaseLlm):
    model: str = "bakiano-offline-fixture-v1"

    async def generate_content_async(
        self,
        llm_request: LlmRequest,
        stream: bool = False,
    ) -> AsyncGenerator[LlmResponse, None]:
        if stream:
            raise ValueError("Offline fixture uses nonstreaming turns")
        results: dict[str, Any] = {}
        for content in llm_request.contents:
            for part in content.parts or []:
                if part.function_response:
                    response = part.function_response
                    if response.name is None:
                        raise ValueError("A tool response must name its capability")
                    body = response.response or {}
                    results[response.name] = body.get("result", body)
        if "finish_decision" in results:
            yield self.response(text="The scoped decision is saved for validation and commit.")
            return
        actions = {
            "request_missing_ingredients",
            "confirm_order",
            "receive_ingredient",
            "prepare_meal",
            "offer_substitution",
            "decline_order",
        }
        if actions & results.keys():
            yield self.response(
                calls=[
                    (
                        "finish_decision",
                        {
                            "summary": "Compared scoped pantry and supplier quotes."
                        },
                    )
                ]
            )
            return
        if "read_order" not in results:
            reads = [
                name
                for name in (
                    "read_order",
                    "read_recipe",
                    "read_pantry",
                    "find_suppliers",
                    "recall_order_memory",
                )
                if name in llm_request.tools_dict
            ]
            if "read_order" not in reads:
                raise ValueError("Offline fixture requires the order capability")
            yield self.response(calls=[(name, {}) for name in reads])
            return
        order = results["read_order"]
        topic = order["event"]
        call: tuple[str, dict[str, Any]]
        if topic in {"household.call", "restaurant.approval"}:
            recipe = results.get("read_recipe", {})
            pantry = {row["ingredient"]: row for row in results.get("read_pantry", [])}
            shortage = topic == "restaurant.approval" or any(
                pantry.get(item["id"], {}).get("on_hand", 0)
                - pantry.get(item["id"], {}).get("reserved", 0)
                < item["quantity"] * order["quantity"]
                for item in recipe.get("ingredients", [])
            )
            suppliers = results.get("find_suppliers", [])
            if shortage and suppliers:
                instructions = llm_request.config.system_instruction
                if isinstance(instructions, types.Content):
                    text = " ".join(part.text or "" for part in instructions.parts or [])
                else:
                    text = str(instructions)
                normalized = " ".join(text.lower().split())
                key = (
                    ("procurement_fee_cents", "estimated_seconds")
                    if ("prioritize the lowest quoted procurement fee" in normalized)
                    else ("estimated_seconds", "procurement_fee_cents")
                )
                selected = min(suppliers, key=lambda row: (row[key[0]], row[key[1]], row["id"]))
                call = ("request_missing_ingredients", {"supplier": selected["id"]})
            elif shortage:
                call = ("decline_order", {"reason": "No open supplier is available."})
            else:
                call = ("confirm_order", {})
        elif topic == "ingredient.arrived":
            call = ("receive_ingredient", {})
        elif topic == "restaurant.cook":
            call = ("prepare_meal", {})
        elif topic == "ingredient.shortage" and order.get("safe_alternative"):
            call = ("offer_substitution", {"substitute": order["safe_alternative"]})
        else:
            call = ("decline_order", {"reason": "No safe available ingredient alternative."})
        yield self.response(calls=[call])

    @staticmethod
    def response(
        *,
        calls: list[tuple[str, dict[str, Any]]] | None = None,
        text: str | None = None,
    ) -> LlmResponse:
        parts = [
            types.Part(function_call=types.FunctionCall(name=name, args=args))
            for name, args in calls or []
        ]
        if text:
            parts.append(types.Part(text=text))
        return LlmResponse(
            content=types.Content(role="model", parts=parts),
            usage_metadata=types.GenerateContentResponseUsageMetadata(
                prompt_token_count=0, candidates_token_count=0
            ),
        )


class OfflineCustomerModel(BaseLlm):
    """Scripted classification fixture, not an LLM or a quality evaluation."""

    model: str = OFFLINE_MODEL

    async def generate_content_async(
        self, llm_request: LlmRequest, stream: bool = False
    ) -> AsyncGenerator[LlmResponse, None]:
        if stream:
            raise ValueError("Offline fixture uses nonstreaming turns")
        if llm_request.tools_dict:
            raise PermissionError("Customer classification cannot invoke tools")
        prompt = next(
            part.text
            for content in llm_request.contents
            if content.role == "user"
            for part in content.parts or []
            if part.text
        )
        body = json.loads(prompt)
        text = body["untrusted_complaint"].lower()
        category: Literal["status", "delay", "refund", "escalate"] = "escalate"
        if not any(word in text for word in ("ignore", "instruction", "policy", "execute")):
            if "refund" in text:
                category = "refund"
            elif any(word in text for word in ("late", "delay")):
                category = "delay"
            elif any(word in text for word in ("status", "where")):
                category = "status"
        advice = Advice(
            category=category,
            reply="Your delivery concern is recorded for review. No refund has been authorized.",
        )
        yield LlmResponse(
            content=types.Content(role="model", parts=[types.Part(text=advice.model_dump_json())]),
            usage_metadata=types.GenerateContentResponseUsageMetadata(
                prompt_token_count=0, candidates_token_count=0
            ),
            model_version=OFFLINE_MODEL,
        )

src/delivery/adk_restaurant.py:
"""Google ADK reasoning over scoped tools; model I/O never holds a SQL connection.

Offline is the default. Vertex requires an explicit approved deployment profile
and durable monetary admission; there is no automatic provider fallback.
"""

import asyncio
import hashlib
import json
import time
from collections.abc import Callable
from typing import TYPE_CHECKING, Any, Literal

from google.adk.agents import LlmAgent
from google.adk.agents.callback_context import CallbackContext
from google.adk.agents.run_config import RunConfig
from google.adk.models.base_llm import BaseLlm
from google.adk.models.llm_request import LlmRequest
from google.adk.models.llm_response import LlmResponse
from google.adk.runners import Runner
from google.adk.sessions import InMemorySessionService
from google.genai import types
from opentelemetry.trace import Span, Status, StatusCode
from psycopg.types.json import Jsonb
from pydantic import BaseModel, ConfigDict, Field

from delivery.adk_contracts import effective_instructions
from delivery.db import connect
from delivery.queue import Event
from delivery.telemetry import (
    mark_error,
    record_model_usage,
    start_span,
    trace_span,
    traced_event,
    traced_tool,
)

if TYPE_CHECKING:
    from delivery.agent_runtime import LocalAgent


class RestaurantPlan(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)

    action: Literal["source", "confirm", "receive", "cook", "offer", "decline"]
    supplier: str | None = Field(default=None, min_length=1, max_length=64)
    substitute: str | None = Field(default=None, min_length=1, max_length=80)
    reason: str | None = Field(default=None, min_length=1, max_length=240)
    summary: str = Field(min_length=1, max_length=500)


class RestaurantTurn:
    """One event/identity-bound capability pack, without a live DB connection."""

    def __init__(
        self,
        agent: "LocalAgent",
        event: Event,
        nonce: str,
        fault: Callable[[str], None] | None = None,
    ) -> None:
        if agent.role.name != "restaurant" or agent.role.policy != "adk" or not agent.role.brain:
            raise PermissionError("A frozen ADK restaurant definition is required")
        self.agent, self.event, self.nonce = agent, event, nonce
        self.brain = agent.role.brain
        self.fault = fault or (lambda stage: None)
        self.action: dict[str, Any] | None = None
        self.plan: RestaurantPlan | None = None
        self.pending_step: int | None = None
        self.model_started: float | None = None
        self.declared_tool_names: frozenset[str] = frozenset()
        self.model_span: Span | None = None

    def sql(self, function: str, *args: Any) -> Any:
        # Function names are literals in this module, never model arguments.
        parameters = (self.event.id, self.event.token, self.event.attempts, self.nonce, *args)
        placeholders = ",".join(["%s"] * len(parameters))
        with connect(self.agent.dsn) as conn:
            row = conn.execute(
                f"SELECT public.{function}({placeholders}) AS data", parameters
            ).fetchone()
            assert row
            return row["data"]

    def invoke(self, name: str, arguments: dict[str, Any] | None = None) -> Any:
        with trace_span(
            "agent.capability",
            attributes={"delivery.agent": "restaurant", "delivery.capability": name},
        ):
            if self.plan is not None:
                raise PermissionError("Decision already finished")
            if name not in self.brain.tools:
                raise PermissionError("Capability is not enabled by the frozen template")
            return self.sql("restaurant_tool", name, Jsonb(arguments or {}))

    def read_order(self) -> dict[str, Any]:
        """Read the current order, incoming event, deadline and safe alternative."""
        return dict(self.invoke("restaurant.order"))

    def read_pantry(self) -> list[dict[str, Any]]:
        """Read only this restaurant's physical stock and reservations."""
        return list(self.invoke("restaurant.pantry"))

    def read_recipe(self) -> dict[str, Any]:
        """Read the frozen recipe and canonical ingredient quantities for this meal."""
        return dict(self.invoke("restaurant.recipe"))

    def find_suppliers(self) -> list[dict[str, Any]]:
        """Find open markets' public fee and estimated lead-time quotes, without private stock."""
        return list(self.invoke("restaurant.suppliers"))

    def recall_order_memory(self, query: str = "") -> Any:
        """Recall current facts for this order; an optional query ranks semantic profiles."""
        from delivery.memory_profiles import project_memory

        profile = self.agent.role.memory
        facts = list(self.invoke("memory.read"))
        if profile is not None and profile.mode == "semantic":
            from delivery.semantic_memory import backend, rank_facts

            with connect(self.agent.dsn) as conn:
                ids, audit = rank_facts(
                    facts, query or f"restaurant {self.event.topic}",
                    {"run": self.agent.scope.run, "store": self.agent.scope.store,
                     "role": "restaurant", "context_type": "order",
                     "context_id": facts[0]["context_id"] if facts else "",
                     "subject": facts[0]["subject"] if facts else ""},
                    backend(conn, self.event),
                )
            # This SQL boundary rechecks the turn nonce and performs a fresh charged
            # recall after network I/O. Its receipt becomes the final ADK memory audit.
            facts = list(self.sql("restaurant_semantic_recall", Jsonb(ids), Jsonb(audit)))
        return project_memory(profile, facts)

    def search_ingredients(self, query: str) -> dict[str, Any]:
        """Classify ingredient matches in this restaurant's index; never reserve stock.

        The operator selects local or Jev review and freezes a separate call/token
        budget. Only ingredient labels and units go to Jev, never order memory.
        """
        from delivery.supply_search_service import search_for_agent

        if self.plan is not None or "supply.search" not in self.brain.tools:
            raise PermissionError("Search capability unavailable")
        recipe = self.read_recipe()
        if query not in {item["id"] for item in recipe["ingredients"]}:
            raise PermissionError("Search can disclose only a canonical current-recipe ingredient")
        with connect(self.agent.dsn) as conn:
            row = conn.execute(
                "SELECT public.supply_search_settings(%s,%s,%s) AS data",
                (self.event.id, self.event.token, self.event.attempts),
            ).fetchone()
            assert row
            mode = row["data"]["provider"]
        return search_for_agent(self.agent, self.event, query, mode)

    def stage(self, name: str, action: str, **arguments: Any) -> dict[str, Any]:
        if self.action is not None:
            raise PermissionError("Stage exactly one business action per event")
        result = self.invoke(name, arguments)
        self.action = {"action": action, **arguments}
        return dict(result)

    def request_missing_ingredients(self, supplier: str) -> dict[str, Any]:
        """Stage sourcing from an open market; SQL calculates shortages and queues requests."""
        if not 1 <= len(supplier) <= 64:
            raise ValueError("Invalid supplier reference")
        return self.stage("restaurant.request_supply", "source", supplier=supplier)

    def confirm_order(self) -> dict[str, Any]:
        """Stage acceptance using physical pantry stock; fails if sourcing is needed."""
        return self.stage("restaurant.confirm", "confirm")

    def receive_ingredient(self) -> dict[str, Any]:
        """Stage receipt of the ingredient named by the current arrival event."""
        return self.stage("restaurant.receive", "receive")

    def prepare_meal(self) -> dict[str, Any]:
        """Stage cooking at its due event, using arrived and consented ingredients."""
        return self.stage("restaurant.cook", "cook")

    def offer_substitution(self, substitute: str) -> dict[str, Any]:
        """Stage a safe alternative offer; a queued household reply must approve it."""
        if not 1 <= len(substitute) <= 80:
            raise ValueError("Invalid alternative")
        return self.stage("restaurant.offer", "offer", substitute=substitute)

    def decline_order(self, reason: str) -> dict[str, Any]:
        """Stage an order decline and release reservations, with a bounded factual reason."""
        if not 1 <= len(reason) <= 240:
            raise ValueError("Invalid reason")
        return self.stage("restaurant.decline", "decline", reason=reason)

    def finish_decision(self, summary: str) -> dict[str, Any]:
        """Finish the staged decision; nothing is committed yet.

        Args:
            summary: Factual explanation of 1 to 500 characters, including spaces.
                Compare quoted values concisely. If rejected, rewrite this text
                without staging another action. Do not truncate a previous answer.
        """
        if self.action is None:
            raise ValueError("Stage an action before finishing")
        if not 1 <= len(summary) <= 500:
            return dict(self.sql("restaurant_contract_reject", "finish_decision", "summary_length"))
        plan = RestaurantPlan(**self.action, summary=summary)
        result = self.invoke("restaurant.finish", {"summary": summary})
        self.plan = plan
        return dict(result)

    def before_model(self, callback_context: CallbackContext, llm_request: LlmRequest) -> None:
        del callback_context
        if self.pending_step is not None:
            raise PermissionError("An unfinished model call cannot be retried")
        body = json.dumps(
            {
                "contents": [
                    c.model_dump(mode="json", exclude_none=True) for c in llm_request.contents
                ],
                "config": llm_request.config.model_dump(mode="json", exclude_none=True),
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode()
        self.pending_step = int(
            self.sql("restaurant_model_admit", len(body), hashlib.sha256(body).hexdigest())
        )
        self.sql("restaurant_model_trace", self.pending_step, Jsonb(json.loads(body)), None, None)
        self.model_started = time.monotonic()
        self.model_span = start_span(
            "agent.model",
            {
                "delivery.agent": "restaurant",
                "gen_ai.system": self.brain.provider,
                "gen_ai.request.model": self.brain.vertex.model if self.brain.vertex else "offline",
                "delivery.model_step": self.pending_step,
            },
        )
        self.fault("before_adk_model")

    def after_model(self, callback_context: CallbackContext, llm_response: LlmResponse) -> None:
        del callback_context
        if llm_response.partial:
            return
        if self.pending_step is None:
            raise PermissionError("Model receipt has no admitted dispatch")
        self.fault("after_adk_model")
        usage = llm_response.usage_metadata
        receipt: dict[str, Any] = {
            "known": usage is not None,
            "model_version": llm_response.model_version,
        }
        if usage is not None:
            receipt.update(usage.model_dump(mode="json", exclude_none=True))
        if self.model_span is not None:
            profile = self.brain.vertex
            record_model_usage(
                self.model_span,
                usage,
                profile.input_usd_per_million if profile else 0.0,
                profile.output_usd_per_million if profile else 0.0,
            )
            self.model_span.set_attribute("delivery.success", not bool(llm_response.error_code))
            if llm_response.error_code:
                self.model_span.set_attribute("error.type", "ModelResponseError")
                self.model_span.set_status(Status(StatusCode.ERROR))
            self.model_span.end()
            self.model_span = None
        self.sql(
            "restaurant_model_trace",
            self.pending_step,
            None,
            Jsonb(
                llm_response.content.model_dump(mode="json", exclude_none=True)
                if llm_response.content
                else {}
            ),
            max(0, round((time.monotonic() - (self.model_started or time.monotonic())) * 1000)),
        )
        self.sql("restaurant_model_complete", self.pending_step, Jsonb(receipt))
        self.pending_step = None
        self.model_started = None

    def build(self, model: BaseLlm) -> LlmAgent:
        from delivery.adk_models import validate_model

        validate_model(self.brain, model)
        registry: dict[str, Callable[..., Any]] = {
            "restaurant.order": self.read_order,
            "restaurant.pantry": self.read_pantry,
            "restaurant.recipe": self.read_recipe,
            "restaurant.suppliers": self.find_suppliers,
            "memory.read": self.recall_order_memory,
            "supply.search": self.search_ingredients,
            "restaurant.request_supply": self.request_missing_ingredients,
            "restaurant.confirm": self.confirm_order,
            "restaurant.receive": self.receive_ingredient,
            "restaurant.cook": self.prepare_meal,
            "restaurant.offer": self.offer_substitution,
            "restaurant.decline": self.decline_order,
            "restaurant.finish": self.finish_decision,
        }
        tools = [tool for capability, tool in registry.items() if capability in self.brain.tools]
        self.declared_tool_names = frozenset(tool.__name__ for tool in tools)
        return LlmAgent(
            name="restaurant",
            model=model,
            instruction=lambda _: effective_instructions(self.brain, self.agent.role.soul),
            tools=[traced_tool("restaurant")(tool) for tool in tools],
            before_model_callback=self.before_model,
            after_model_callback=self.after_model,
            before_tool_callback=self.before_tool,
            after_tool_callback=self.after_tool,
            generate_content_config=types.GenerateContentConfig(
                temperature=0,
                max_output_tokens=self.brain.output_tokens,
                tool_config=types.ToolConfig(
                    function_calling_config=types.FunctionCallingConfig(
                        mode=types.FunctionCallingConfigMode.VALIDATED,
                        allowed_function_names=sorted(self.declared_tool_names),
                    )
                ),
                thinking_config=(
                    types.ThinkingConfig(thinking_level=types.ThinkingLevel.MINIMAL)
                    if self.brain.vertex and self.brain.vertex.model.startswith("gemini-3")
                    else types.ThinkingConfig(thinking_budget=0)
                ),
            ),
        )

    def before_tool(
        self, tool: Any, args: dict[str, Any], tool_context: Any
    ) -> dict[str, Any] | None:
        try:
            return self._before_tool(tool, args, tool_context)
        except Exception:
            # Validation rejects before the normal tool wrapper can run.
            with trace_span(
                "agent.tool",
                attributes={"delivery.agent": "restaurant", "delivery.tool": tool.name},
            ):
                raise

    def _before_tool(
        self, tool: Any, args: dict[str, Any], tool_context: Any
    ) -> dict[str, Any] | None:
        del tool_context
        fields = {
            "read_order": set(),
            "read_pantry": set(),
            "read_recipe": set(),
            "find_suppliers": set(),
            "recall_order_memory": set(),
            "search_ingredients": {"query"},
            "request_missing_ingredients": {"supplier"},
            "confirm_order": set(),
            "receive_ingredient": set(),
            "prepare_meal": set(),
            "offer_substitution": {"substitute"},
            "decline_order": {"reason"},
            "finish_decision": {"summary"},
        }
        if self.plan is not None:
            raise PermissionError("Decision already finished")
        if tool.name in fields and tool.name not in self.declared_tool_names:
            raise PermissionError("Tool is not enabled by the frozen template")
        # Do not alias or execute an invented name. Its completed model response
        # may receive one bounded correction; scope/argument violations stay fatal.
        if tool.name not in fields:
            if set(args) - {"summary"} or any(type(value) is not str for value in args.values()):
                raise PermissionError("Unknown tool cannot carry scope or arbitrary arguments")
            with trace_span(
                "agent.tool",
                attributes={
                    "delivery.agent": "restaurant",
                    "delivery.tool": tool.name,
                    "delivery.success": False,
                    "error.type": "UnknownTool",
                },
            ) as span:
                span.set_status(Status(StatusCode.ERROR))
                return dict(self.sql("restaurant_contract_reject", tool.name, "unknown_tool"))
        if set(args) != fields[tool.name] or any(type(value) is not str for value in args.values()):
            raise PermissionError("Tool arguments cannot alter scope or schema")
        return None

    def after_tool(
        self, tool: Any, args: dict[str, Any], tool_context: Any, tool_response: Any
    ) -> None:
        del args, tool_response
        if tool.name == "finish_decision" and self.plan is not None:
            # The saved factual plan is the response. Do not pay for an extra
            # summarization turn after the terminal tool has sealed it.
            tool_context.actions.skip_summarization = True

    async def run(self, model: BaseLlm) -> RestaurantPlan:
        service = InMemorySessionService()
        session = await service.create_session(
            app_name="bakiano_restaurant", user_id=self.agent.scope.agent_id
        )
        runner = Runner(
            app_name="bakiano_restaurant", agent=self.build(model), session_service=service
        )
        try:
            async for _ in runner.run_async(
                user_id=self.agent.scope.agent_id,
                session_id=session.id,
                new_message=types.Content(
                    role="user",
                    parts=[
                        types.Part(
                            text=json.dumps(
                                {
                                    "event_id": self.event.id,
                                    "task": "Inspect this order through scoped tools.",
                                }
                            )
                        )
                    ],
                ),
                run_config=RunConfig(max_llm_calls=self.brain.model_calls_per_event),
            ):
                pass
        finally:
            await runner.close()
        if self.plan is None:
            raise ValueError("Model did not finish a staged decision")
        return self.plan


@traced_event("agent.restaurant")
def ensure_restaurant_result(
    agent: "LocalAgent",
    event: Event,
    *,
    model: BaseLlm | None = None,
    fault: Callable[[str], None] | None = None,
    router_reviewer: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
) -> bool:
    with connect(agent.dsn) as conn:
        row = conn.execute(
            "SELECT public.restaurant_turn_begin(%s,%s,%s) AS data",
            (event.id, event.token, event.attempts),
        ).fetchone()
        assert row
        receipt = row["data"]
    if receipt["state"] == "succeeded":
        return True
    if receipt["state"] in {"failed", "unknown", "applied"}:
        raise RuntimeError("RestaurantTurnUnavailable")
    if not receipt["dispatch"]:
        return False
    from delivery.adk_models import create_restaurant_model

    turn = RestaurantTurn(agent, event, receipt["nonce"], fault)
    turn.fault("after_adk_begin")
    try:

        async def run() -> RestaurantPlan:
            async def decide() -> RestaurantPlan:
                if turn.brain.routing:
                    from delivery.jev_routing import route_turn

                    if route_turn(turn, router_reviewer):
                        assert turn.plan
                        return turn.plan
                return await turn.run(model or create_restaurant_model(turn.brain))

            return await asyncio.wait_for(decide(), turn.brain.timeout_seconds)

        plan = asyncio.run(run())
        turn.fault("before_adk_save")
        turn.sql("restaurant_turn_save", Jsonb(plan.model_dump()), None)
        turn.fault("after_adk_save")
        return True
    except Exception as exc:
        if turn.model_span is not None:
            mark_error(turn.model_span, exc)
        turn.sql("restaurant_turn_save", None, type(exc).__name__)
        raise
    finally:
        if turn.model_span is not None:
            turn.model_span.end()
            turn.model_span = None

src/delivery/agent_runtime.py:
"""Shared local worker: authenticated scope, fixed tools, private memory and budgets.

Policies receive tools and a typed event, never an operator connection or city snapshot.
There are deliberately no file, SQL, network, code-execution or direct-agent tools.
"""

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any

from psycopg.types.json import Jsonb
from pydantic import BaseModel, ConfigDict, Field

from delivery.agent_specs import RoleSpec
from delivery.db import Connection, connect
from delivery.inventory import receive, release, reserve
from delivery.queue import Event, Queue, persist_trace_context, publish
from delivery.telemetry import active, trace_fields, trace_span, traced_event


class BasketRequest(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    basket: str = Field(min_length=1, max_length=100)
    store: str = Field(pattern=r"^store-([1-9]|1[0-2]|(?:node|way|relation)/[0-9]+)$")
    sku: str = Field(min_length=1, max_length=512)
    quantity: int = Field(gt=0)
    expires_sim: int = Field(ge=0)
    deliver: bool = False


class ShipmentDelay(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    shipment: str = Field(min_length=1, max_length=100)
    expected_sim: int = Field(ge=0)


class ShipmentRef(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    shipment: str = Field(min_length=1, max_length=100)


class BasketRef(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    basket: str = Field(min_length=1, max_length=100)


class BudgetExceeded(RuntimeError):
    pass


@dataclass(frozen=True)
class AgentScope:
    run: str
    store: str
    agent_id: str
    definition_hash: str


class ScopedTools:
    """A fixed capability registry; all scope comes from authenticated session_user."""

    def __init__(self, conn: Connection, scope: AgentScope, role: RoleSpec, event: Event) -> None:
        self.__conn = conn
        self.scope = scope
        self.role = role
        self.event = event
        self.calls: list[str] = []
        self.memory_writes: list[dict[str, Any]] = []
        self.memory_reads: list[dict[str, Any]] = []
        self.inference_receipt: dict[str, Any] | None = None
        ticket = conn.execute(
            """SELECT b.slots FROM agent_event_budgets b JOIN events e
            ON e.id=b.event_id WHERE b.event_id=%s AND b.attempt=%s AND e.state='leased'
            AND e.lease_token=%s AND e.lease_until>clock_timestamp()""",
            (event.id, event.attempts, event.token),
        ).fetchone()
        if not ticket:
            raise BudgetExceeded("Active event lease and durable budget required")
        row = conn.execute("SELECT public.agent_clock() AS sim").fetchone()
        assert row
        self.sim = int(row["sim"])

    def invoke(self, name: str, **arguments: Any) -> Any:
        with trace_span(
            "agent.tool", attributes={"delivery.agent": self.role.name, "delivery.tool": name}
        ):
            return self._invoke(name, **arguments)

    def _invoke(self, name: str, **arguments: Any) -> Any:
        if name not in self.role.tools:
            raise PermissionError("Tool is not granted to this role")
        for key in ("run", "run_id", "store", "owner", "namespace", "agent_id"):
            if key in arguments:
                raise PermissionError("Tool scope is bound to authenticated identity")
        if len(self.calls) >= self.role.limits.tool_calls_per_event:
            raise BudgetExceeded("Per-event tool limit exhausted")
        registry: dict[str, Callable[..., Any]] = {
            "inventory.read": self._read,
            "inventory.reserve": self._reserve,
            "inventory.release": self._release,
            "inventory.delay": self._delay,
            "inventory.receive": self._receive,
            "memory.read": self._recall,
            "memory.write": self._remember,
            "queue.publish": self._publish,
            "fulfillment.read": self._workflow_read,
            "fulfillment.pick": self._workflow_pick,
            "dispatch.read": self._workflow_read,
            "dispatch.assign": self._workflow_assign,
            "dispatch.complete": self._workflow_complete,
            "dispatch.recover": self._recover,
            "dispatch.defer": self._defer,
            "courier.read": self._courier_read,
            "courier.accept": self._courier_accept,
            "judge.read": self._judge_read,
            "judge.review": self._judge_review,
            "supply.read": self._supply_read,
            "supply.command": self._supply_command,
        }
        if name not in registry:
            raise PermissionError("Unknown tool")
        # Memory and publish functions charge internally so direct SQL cannot skip admission.
        if name not in {"memory.read", "memory.write", "queue.publish"}:
            consumed = self.__conn.execute(
                "SELECT public.agent_consume_tool(%s,%s,%s,%s) AS consumed",
                (self.event.id, self.event.token, self.event.attempts, name),
            ).fetchone()
            if not consumed or not consumed["consumed"]:
                raise BudgetExceeded("Reserved tool slots exhausted")
        self.calls.append(name)
        return registry[name](**arguments)

    def _json_command(self, query: str, parameters: tuple[Any, ...]) -> dict[str, Any]:
        row = self.__conn.execute(query, parameters).fetchone()
        assert row
        return dict(row["data"])

    def _supply_read(self, order: str) -> dict[str, Any]:
        return self._json_command("SELECT public.supply_context(%s) AS data", (order,))

    def _supply_command(self) -> dict[str, Any]:
        return self._json_command(
            "SELECT public.supply_command(%s,%s,%s) AS data",
            (self.event.id, self.event.token, self.event.attempts),
        )

    def _recover(self, basket: str, attempt: int) -> dict[str, Any]:
        return self._json_command("SELECT dispatch_recover(%s,%s) AS data", (basket, attempt))

    def _defer(self, basket: str) -> dict[str, Any]:
        return self._json_command("SELECT dispatch_defer(%s) AS data", (basket,))

    def _courier_read(self, basket: str, attempt: int) -> dict[str, Any]:
        return self._json_command("SELECT courier_context(%s,%s) AS data", (basket, attempt))

    def _courier_accept(self, basket: str, attempt: int) -> dict[str, Any]:
        return self._json_command("SELECT courier_accept(%s,%s) AS data", (basket, attempt))

    def _judge_read(self, basket: str, attempt: int) -> dict[str, Any]:
        return self._json_command("SELECT judge_context(%s,%s) AS data", (basket, attempt))

    def _judge_review(
        self, basket: str, attempt: int, courier: str | None, route: list[int] | None
    ) -> dict[str, Any]:
        return self._json_command(
            "SELECT judge_review(%s,%s,%s,%s) AS data",
            (basket, attempt, courier, Jsonb(route) if route is not None else None),
        )

    def _workflow_read(self, basket: str) -> dict[str, Any]:
        row = self.__conn.execute(
            "SELECT public.workflow_context(%s) AS data", (basket,)
        ).fetchone()
        assert row
        return dict(row["data"])

    def _workflow_pick(self, basket: str) -> dict[str, Any]:
        row = self.__conn.execute(
            "SELECT public.fulfillment_pick(%s) AS data", (basket,)
        ).fetchone()
        assert row
        return dict(row["data"])

    def _workflow_assign(self, basket: str, courier: str, route: list[int]) -> dict[str, Any]:
        row = self.__conn.execute(
            "SELECT public.dispatch_assign(%s,%s,%s) AS data", (basket, courier, Jsonb(route))
        ).fetchone()
        assert row
        return dict(row["data"])

    def _workflow_complete(self, basket: str) -> dict[str, Any]:
        row = self.__conn.execute(
            "SELECT public.dispatch_complete(%s) AS data", (basket,)
        ).fetchone()
        assert row
        return dict(row["data"])

    def _read(self, sku: str | None = None) -> dict[str, Any]:
        stock = self.__conn.execute(
            """SELECT sku,on_hand,reserved,on_hand-reserved AS available_now,
            version FROM lab_stock WHERE run_id=%s AND store=%s AND (%s::text IS NULL OR sku=%s)
            ORDER BY sku""",
            (self.scope.run, self.scope.store, sku, sku),
        ).fetchall()
        row = self.__conn.execute("SELECT public.agent_catalogue() AS products").fetchone()
        assert row
        products = [
            p for p in row["products"] if sku is None or f"{p['source']}:{p['listing_id']}" == sku
        ]
        return {
            "as_of_sim": self.sim,
            "store": self.scope.store,
            "products": products,
            "stock": stock,
        }

    def _reserve(self, basket: str, sku: str, quantity: int, expires_sim: int) -> str:
        return reserve(
            self.__conn,
            self.scope.run,
            basket,
            self.scope.store,
            sku,
            quantity,
            self.sim,
            expires_sim,
        )

    def _release(self, basket: str) -> str:
        return release(self.__conn, self.scope.run, basket, self.sim)

    def _delay(self, shipment: str, expected_sim: int) -> dict[str, Any]:
        if expected_sim < self.sim:
            raise ValueError("Shipment ETA cannot precede current time")
        row = self.__conn.execute(
            """UPDATE lab_shipments SET expected_sim=%s,status='delayed'
            WHERE run_id=%s AND id=%s AND status!='received' AND expected_sim<=%s RETURNING id""",
            (expected_sim, self.scope.run, shipment, expected_sim),
        ).fetchone()
        if not row:
            raise ValueError("Unknown shipment or outdated delay")
        return {"shipment": shipment, "expected_sim": expected_sim}

    def _receive(self, shipment: str) -> dict[str, Any]:
        row = self.__conn.execute(
            "SELECT expected_sim,status FROM lab_shipments WHERE run_id=%s AND id=%s",
            (self.scope.run, shipment),
        ).fetchone()
        if not row:
            raise ValueError("Unknown shipment")
        deferred = row["status"] != "received" and self.sim < row["expected_sim"]
        return {
            "shipment": shipment,
            "deferred": deferred,
            "received": False
            if deferred
            else receive(self.__conn, self.scope.run, shipment, self.sim),
        }

    def _recall(
        self, kinds: list[str] | None = None, limit: int = 8, query: str | None = None,
    ) -> list[dict[str, Any]]:
        if (
            type(limit) is not int
            or not 1 <= limit <= 16
            or (
                kinds is not None
                and (
                    type(kinds) is not list
                    or len(kinds) > 9
                    or any(type(kind) is not str for kind in kinds)
                )
            )
        ):
            raise ValueError("Invalid typed recall filters or limit")
        row = self.__conn.execute(
            "SELECT public.agent_memory_recall(%s,%s,%s,%s,%s) AS facts",
            (
                self.event.id,
                self.event.token,
                self.event.attempts,
                Jsonb(kinds) if kinds is not None else None,
                limit,
            ),
        ).fetchone()
        assert row
        facts = list(row["facts"])
        self.memory_reads.append(
            {
                "event_id": self.event.id,
                "limit": limit,
                "kinds": kinds,
                "facts": [
                    {
                        k: fact[k]
                        for k in (
                            "fact_id",
                            "kind",
                            "version",
                            "event_id",
                            "context_id",
                            "expires_sim",
                        )
                    }
                    for fact in facts
                ],
            }
        )
        if self.role.memory is not None and self.role.memory.mode == "semantic":
            from delivery.semantic_memory import backend, rank_facts

            if len(self.calls) >= self.role.limits.tool_calls_per_event:
                raise BudgetExceeded("Semantic recall requires a second fenced memory read")
            self.calls.append("memory.read")
            index = backend(self.__conn, self.event)
            ids, audit = rank_facts(
                facts, query or f"{self.role.name} {self.event.topic}",
                {"run": self.scope.run, "store": self.scope.store, "role": self.role.name,
                 "context_type": facts[0]["context_type"] if facts else "order",
                 "context_id": facts[0]["context_id"] if facts else "",
                 "subject": facts[0]["subject"] if facts else ""}, index,
            )
            # External ranking cannot grant a fact or outlive its lease/TTL/version.
            current = self.__conn.execute(
                "SELECT public.agent_memory_recall(%s,%s,%s,%s,%s) AS facts",
                (self.event.id, self.event.token, self.event.attempts,
                 Jsonb(kinds) if kinds is not None else None, limit),
            ).fetchone()
            assert current
            fresh = {int(f["fact_id"]): f for f in current["facts"]}
            facts = [fresh[i] for i in ids if i in fresh]
            audit["returned_fact_ids"] = [f["fact_id"] for f in facts]
            self.memory_reads[-1]["semantic"] = audit
        return facts

    def _remember(self, kind: str, body: dict[str, Any], ttl_seconds: int = 3600) -> None:
        from delivery.typed_memory import validate_fact

        if type(ttl_seconds) is not int or not 1 <= ttl_seconds <= 86400:
            raise ValueError("Invalid typed memory TTL")
        validated = validate_fact(kind, body, self.role.name, self.event.topic)
        result = self._json_command(
            "SELECT public.agent_memory_record(%s,%s,%s,%s,%s,%s) AS data",
            (
                self.event.id,
                self.event.token,
                self.event.attempts,
                kind,
                Jsonb(validated),
                ttl_seconds,
            ),
        )
        self.memory_writes.append(result)

    def _publish(
        self, topic: str, payload: dict[str, Any], key: str, due_sim: int | None = None
    ) -> int:
        if topic not in self.role.emits:
            raise PermissionError("Event topic is not granted to this role")
        if any(k in payload for k in ("run", "run_id", "store", "owner", "namespace", "agent_id")):
            raise PermissionError("Outbound scope cannot be supplied by policy")
        return publish(
            self.__conn,
            run_id=self.scope.run,
            producer=self.role.name,
            topic=topic,
            payload=payload,
            key=key,
            trace_id=self.event.trace_id,
            parent_id=self.event.id,
            target_store=None,
            due_sim=self.sim if due_sim is None else due_sim,
            lease_token=self.event.token,
            event_attempt=self.event.attempts,
        )


class InventoryPolicy:
    """Deterministic baseline policy; the runtime also supports future decision adapters."""

    def decide(self, event: Event, tools: ScopedTools) -> dict[str, Any]:
        body = event.payload
        context = tools.invoke("inventory.read", sku=body.get("sku"))
        memory = tools.invoke("memory.read")
        if event.topic == "basket.requested":
            request = BasketRequest.model_validate(body)
            if request.store != tools.scope.store:
                raise PermissionError("Basket is outside this store")
            status = tools.invoke(
                "inventory.reserve",
                basket=request.basket,
                sku=request.sku,
                quantity=request.quantity,
                expires_sim=request.expires_sim,
            )
            if request.deliver and status == "reserved":
                tools.invoke(
                    "queue.publish",
                    topic="basket.reserved",
                    payload={"basket": request.basket},
                    key=request.basket,
                )
            detail = {
                "basket": request.basket,
                "status": status,
                "rule": "reserve only confirmed available units; reject insufficient stock",
            }
        elif event.topic == "reservation.expire":
            basket = BasketRef.model_validate(body).basket
            detail = {
                "basket": basket,
                "status": tools.invoke("inventory.release", basket=basket),
                "rule": "release unused reservation once at simulation deadline",
            }
        elif event.topic == "shipment.delayed":
            delay = ShipmentDelay.model_validate(body)
            detail = tools.invoke(
                "inventory.delay", shipment=delay.shipment, expected_sim=delay.expected_sim
            )
            tools.invoke(
                "queue.publish",
                topic="shipment.received",
                payload={"shipment": delay.shipment},
                key=f"{delay.shipment}:{delay.expected_sim}",
                due_sim=delay.expected_sim,
            )
            detail["rule"] = "expected supply is a forecast, not sellable stock"
        elif event.topic == "shipment.received":
            shipment = ShipmentRef.model_validate(body).shipment
            detail = tools.invoke("inventory.receive", shipment=shipment)
            detail["rule"] = "ignore obsolete receipt; add units once at confirmed arrival"
        else:
            raise PermissionError("Unsupported event")
        from delivery.typed_memory import outcome_fact

        tools.invoke("memory.write", **outcome_fact("inventory", event.topic, detail))
        tools.invoke("queue.publish", topic="inventory.decided", payload=detail, key=str(event.id))
        return {
            **detail,
            "scope": {"run": tools.scope.run, "store": tools.scope.store},
            "role_hash": tools.scope.definition_hash,
            "policy": tools.role.policy,
            "memory_hits": len(memory),
            "observed_state": context,
            "tools": tools.calls,
        }


@dataclass(frozen=True)
class LocalAgent:
    scope: AgentScope
    role: RoleSpec
    dsn: str = field(repr=False)
    cloud_endpoint: str | None = None

    def claim(self, *, lease_seconds: float = 45) -> Event | None:
        with connect(self.dsn) as conn:
            row = conn.execute("SELECT public.agent_clock() AS sim").fetchone()
            assert row
        return Queue(self.dsn, lease_seconds).claim(
            self.role.name, self.scope.run, row["sim"], accepted_topics=self.role.accepts
        )

    def reserve_budget(self, event: Event) -> bool:
        self._validate(event)
        with connect(self.dsn) as conn:
            row = conn.execute(
                "SELECT public.agent_reserve_budget(%s,%s,%s) AS reservation",
                (event.id, event.token, event.attempts),
            ).fetchone()
        return bool(row and row["reservation"]["status"] == "reserved")

    def _validate(self, event: Event) -> None:
        if str(event.run_id) != self.scope.run or event.target_store != self.scope.store:
            raise PermissionError("Event is outside authenticated scope")
        if event.topic not in self.role.accepts:
            raise PermissionError("Event is outside role subscriptions")

    def handle(self, conn: Connection, event: Event) -> None:
        self._validate(event)
        ticket = conn.execute(
            "SELECT slots FROM agent_event_budgets WHERE event_id=%s AND attempt=%s",
            (event.id, event.attempts),
        ).fetchone()
        if not ticket:
            raise BudgetExceeded("A durable budget reservation is required")
        tools = ScopedTools(conn, self.scope, self.role, event)
        if self.role.policy == "gcp_ai":
            from delivery.durable_inference import saved_result

            tools.inference_receipt = saved_result(conn, self, event)
        if self.role.policy == "adk":
            from delivery.typed_memory import outcome_fact

            row = conn.execute(
                "SELECT public.restaurant_apply(%s,%s,%s) AS data",
                (event.id, event.token, event.attempts),
            ).fetchone()
            assert row
            detail = dict(row["data"])
            assert self.role.brain
            detail["policy"] = (
                "google_adk_jev_first"
                if self.role.brain.routing
                else f"google_adk_{self.role.brain.provider}"
            )
            tools.memory_reads.append(
                {
                    "event_id": event.id,
                    "limit": 8,
                    "kinds": None,
                    "facts": [
                        {
                            key: fact[key]
                            for key in (
                                "fact_id",
                                "kind",
                                "version",
                                "event_id",
                                "context_id",
                                "expires_sim",
                            )
                        }
                        for fact in detail["adk"]["memory"]
                    ],
                }
            )
            tools.invoke("memory.write", **outcome_fact("restaurant", event.topic, detail))
        elif self.role.name in {"household", "restaurant", "market"}:
            from delivery.supply_policy import SupplyPolicy

            detail = SupplyPolicy().decide(event, tools)
        elif self.role.name == "inventory":
            detail = InventoryPolicy().decide(event, tools)
        else:
            from delivery.workflow_policy import WorkflowPolicy

            detail = WorkflowPolicy().decide(event, tools)
        detail["reserved_tool_slots"] = ticket["slots"]
        if telemetry := trace_fields():
            detail["telemetry"] = telemetry
        # Persist actual writes with the decision/ACK transaction, so order
        # inspection survives TTL cleanup without changing agent recall access.
        detail["memory_writes"] = tools.memory_writes
        detail["memory_reads"] = tools.memory_reads
        if tools.inference_receipt is not None:
            from delivery.durable_inference import apply_receipt

            receipt = tools.inference_receipt
            detail["inference_prepare_reads"] = {
                "request_id": receipt["id"],
                "request_hash": receipt["request_hash"],
                "event_id": receipt["event_id"],
                "attempt": receipt["prepared_attempt"],
                "tools": ["judge.read", "memory.read"],
                "facts": [
                    {
                        key: fact[key]
                        for key in (
                            "fact_id",
                            "kind",
                            "version",
                            "event_id",
                            "context_id",
                            "expires_sim",
                        )
                    }
                    for fact in receipt["memory"]
                ],
            }
            apply_receipt(conn, event, tools.inference_receipt)
        conn.execute(
            """INSERT INTO decisions(run_id,sim_time,agent,order_id,event_id,action,detail)
            VALUES (%s,%s,%s,%s,%s,%s,%s)""",
            (
                self.scope.run,
                tools.sim,
                self.scope.agent_id,
                event.payload.get("basket"),
                event.id,
                event.topic,
                Jsonb(detail),
            ),
        )

    @traced_event("agent.process")
    def process(self, event: Event, *, fault: Callable[[str], None] | None = None) -> bool:
        from delivery.durable_inference import checkpoint, ensure_result

        if not self.reserve_budget(event):
            Queue(self.dsn).fail(event, "BudgetExceeded")
            return False
        if active():
            with connect(self.dsn) as conn:
                persist_trace_context(conn, event)
        if self.role.policy == "gcp_ai":
            try:
                if not ensure_result(self, event, fault=fault):
                    return False
            except Exception as exc:
                Queue(self.dsn).fail(event, type(exc).__name__)
                return False
        if self.role.policy == "adk":
            from delivery.adk_restaurant import ensure_restaurant_result

            try:
                if not ensure_restaurant_result(self, event, fault=fault):
                    return False
            except Exception as exc:
                Queue(self.dsn).fail(event, type(exc).__name__)
                return False
        checkpoint(fault, "before_apply")

        def apply(conn: Connection, current: Event) -> None:
            self.handle(conn, current)
            checkpoint(fault, "after_apply_before_ack")

        processed = Queue(self.dsn).process(event, apply)
        if processed:
            checkpoint(fault, "after_apply")
        return processed


def create_agent(
    dsn: str, *, agent_mode: str = "local", cloud_endpoint: str | None = None
) -> LocalAgent:
    """Scope is read from the authenticated database login, never from a prompt/event."""
    with connect(dsn) as conn:
        row = conn.execute(
            "SELECT public.agent_scope() AS scope,public.agent_definition() AS definition"
        ).fetchone()
    if not row or not row["scope"] or not row["definition"]:
        raise PermissionError("Authenticated agent binding required")
    if agent_mode not in {"local", "gcp_ai"}:
        raise ValueError("Unknown agent mode")
    data = row["scope"]
    role = RoleSpec.model_validate(row["definition"])
    if role.digest != data["definition_hash"]:
        raise PermissionError("Role definition hash mismatch")
    if role.name == "judge":
        expected = "gcp_ai" if agent_mode == "gcp_ai" else "deterministic"
        if role.policy != expected:
            raise ValueError("Agent mode differs from frozen role")
        if role.policy == "gcp_ai" and not cloud_endpoint:
            raise ValueError("Cloud judge endpoint required")
    return LocalAgent(
        AgentScope(data["run_id"], data["store"], data["agent_id"], data["definition_hash"]),
        role,
        dsn,
        cloud_endpoint,
    )


# Compatibility for existing inventory workers; both use the same authenticated factory.
create_inventory_agent = create_agent

